function CharacterTable({ nodes, select, add }: { nodes: Entity[]; select: (id: string) => void; add: () => void }) { const [extra, setExtra] = useState(false); return <><h1>Персонажи</h1><p>Одна карточка на личность. Обозначения в сценах могут отличаться от имени, известного герою в этот момент.</p><label><input type="checkbox" checked={extra} onChange={e => setExtra(e.target.checked)} /> Показать роль и обозначения</label><table><thead><tr><th>Персонаж</th><th>Описание</th>{extra && <><th>Роль</th><th>Обозначения в сценах</th></>}</tr></thead><tbody>{nodes.map(c => <tr key={c.id}><td><button onClick={() => select(c.id)}>{c.title}</button></td><td><button className="profile-summary" onClick={() => select(c.id)}>{c.content ? `${c.content.slice(0, 320)}${c.content.length > 320 ? '…' : ''}` : 'Отдельное описание в источниках не найдено; откройте связанные сцены.'}</button></td>{extra && <><td>{c.fields?.role}</td><td>{c.fields?.aliases?.join(', ')}</td></>}</tr>)}</tbody></table><button onClick={add}>Добавить персонажа</button></>; }
type ImportPageProps = {run:(fn:()=>Promise<any>)=>Promise<any>;reload:()=>Promise<any>;imported:(id:string)=>void};
